using Licitaciones.Domain.Proveedores;
using Licitaciones.Application.Ofertas;
namespace Licitaciones.Application.Proveedores;
public sealed class GestionarProveedoresService(IProveedorRepository repo, IOfertaRepository ofertas, TimeProvider? reloj = null) { private readonly TimeProvider reloj = reloj ?? TimeProvider.System; public Task<IReadOnlyList<Proveedor>> ListarAsync(CancellationToken c = default) => repo.ListarAsync(c); public Task<Proveedor> ObtenerAsync(Guid id, CancellationToken c = default) => repo.ObtenerPorIdAsync(id, c).ContinueWith(t => t.Result ?? throw new KeyNotFoundException("El proveedor no existe."), c); public async Task EditarAsync(Guid id, string nombre, CancellationToken c = default) { var p = await ObtenerAsync(id, c); p.Editar(nombre, reloj.GetUtcNow()); await repo.AgregarAsync(p, c); } public async Task EliminarAsync(Guid id, CancellationToken c = default) { var p = await ObtenerAsync(id, c); if ((await ofertas.ListarAsync(null, id, c)).Count > 0) throw new InvalidOperationException("No se puede eliminar un proveedor con ofertas."); await repo.EliminarAsync(p, c); } }
